mapper.select:
SELECT hit.id, hit.tenant_id, hit.rule_code, hit.business_type, hit.business_id, hit.threshold_value, hit.actual_value, hit.effect, hit.hit_result, hit.created_time FROM sys_business_rule_hit_record hit WHERE (hit.business_id IS NULL OR NOT EXISTS ( SELECT 1 FROM sys_business_rule_hit_record newer WHERE newer.tenant_id = hit.tenant_id AND newer.rule_code = hit.rule_code AND newer.business_type = hit.business_type AND newer.business_id = hit.business_id AND (newer.created_time > hit.created_time OR ((newer.created_time = hit.created_time OR (newer.created_time IS NULL AND hit.created_time IS NULL)) AND newer.id > hit.id) OR (hit.created_time IS NULL AND newer.created_time IS NOT NULL)) ))
AND hit.rule_code LIKE CONCAT('%', #{ruleCode}, '%')
AND hit.business_type = #{businessType}
AND hit.hit_result = #{hitResult}
ORDER BY hit.created_time DESC, hit.id DESC
